// Let's generate the comprehensive taxonomy module
let fileContent = `/**
 * Comprehensive Clinical Category & Symptom Taxonomy for AyurSetu
 * SIH 2026 Problem 26047 - Ministry of Ayush & Health Informatics
 * 
 * Expands triage coverage to 30 targeted clinical categories with exactly 10 dedicated
 * SOCRATES, Dashavidha, and Red-Flag questions per category.
 */

import { AdaptiveQuestion, ClinicalPurpose, QuestionOptionItem } from "./adaptive-question-generator";

export interface ExtendedCategoryProfile {
  id: string;
  category: string;
  nameHi: string;
  nameEn: string;
  keywords: string[];
  problemsDetector: (text: string) => string[];
  questionTemplates: (lang: "hi" | "en") => AdaptiveQuestion[];
  redFlagHints: string[];
}

export const EXTENDED_CLINICAL_CATEGORIES: Record<string, ExtendedCategoryProfile> = {
`;

for (const cat of categoriesData) {
  fileContent += `  ${cat.id}: {
    id: "${cat.id}",
    category: "${cat.category}",
    nameHi: "${cat.nameHi}",
    nameEn: "${cat.nameEn}",
    keywords: ${JSON.stringify(cat.keywords)},
    problemsDetector: (text: string) => [
      "${cat.problem}",
      "Detailed clinical triage for ${cat.nameEn}"
    ],
    redFlagHints: [
      "${cat.redFlag}"
    ],
    questionTemplates: (lang: "hi" | "en"): AdaptiveQuestion[] => [
`;

  for (const q of cat.questions) {
    const [qId, purpose, hiText, enText, options] = q;
    fileContent += `      {
        id: "${qId}",
        text: lang === "hi" ? ${JSON.stringify(hiText)} : ${JSON.stringify(enText)},
        textEn: ${JSON.stringify(enText)},
        type: "single_choice",
        priority: "${purpose === 'red_flag' || purpose === 'severity' ? 'high' : 'medium'}",
        clinicalPurpose: "${purpose}",
        options: [
`;
    for (const opt of options) {
      const [val, optHi, optEn, isRf] = opt;
      fileContent += `          { value: "${val}", labelHi: ${JSON.stringify(optHi)}, labelEn: ${JSON.stringify(optEn)}${isRf ? ', isRedFlag: true' : ''} },\n`;
    }
    fileContent += `        ],
      },\n`;
  }

  fileContent += `    ],
  },\n\n`;
}

fileContent += `};

/**
 * Returns a list of all 30 category names and metadata for doctors and triage systems
 */
export function getAllExtendedCategories() {
  return Object.values(EXTENDED_CLINICAL_CATEGORIES).map(c => ({
    id: c.id,
    category: c.category,
    nameHi: c.nameHi,
    nameEn: c.nameEn,
    questionCount: 10,
    keywordsCount: c.keywords.length
  }));
}
`;

fs.writeFileSync(path.join(__dirname, '../lib/engine/clinical-categories-taxonomy.ts'), fileContent, 'utf8');
